import React, { useState, useRef, useEffect } from 'react';
import { Terminal, X, Send, Loader2, Sparkles } from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import { ChatMessage } from '../types';
import { SYSTEM_INSTRUCTION } from '../constants';

const TerminalChat: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: 'Initialize sequence... Ask me anything about the Launch Event!' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      if (!process.env.API_KEY) {
        throw new Error("API Key missing");
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Construct history for context
      const history = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
      }));

      const chat = ai.chats.create({
        model: 'gemini-2.5-flash-latest',
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
        },
        history: history
      });

      const response = await chat.sendMessage({ message: userMsg.text });

      const text = response.text || "Connection interrupted. Try again.";

      setMessages(prev => [...prev, { role: 'model', text }]);

    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, { role: 'model', text: "Error: Could not connect to the mainframe. (Check API Key)" }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Button */}
      <button
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-full bg-terminal-green text-terminal-black shadow-[0_0_20px_rgba(16,185,129,0.5)] transition-all duration-300 hover:scale-110 ${isOpen ? 'scale-0 opacity-0' : 'scale-100 opacity-100'}`}
      >
        <Terminal size={24} />
      </button>

      {/* Chat Window */}
      <div className={`fixed bottom-6 right-6 w-[90vw] md:w-96 bg-gray-900 border border-terminal-green/30 rounded-lg shadow-2xl z-50 transition-all duration-300 transform origin-bottom-right flex flex-col overflow-hidden ${isOpen ? 'scale-100 opacity-100 translate-y-0' : 'scale-95 opacity-0 translate-y-10 pointer-events-none'}`} style={{ maxHeight: '600px', height: '80vh' }}>

        {/* Header */}
        <div className="flex items-center justify-between p-3 bg-gray-950 border-b border-gray-800">
          <div className="flex items-center gap-2">
            <Sparkles size={16} className="text-terminal-green" />
            <span className="font-mono text-sm font-bold text-terminal-green">Event_AI.exe</span>
          </div>
          <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-white">
            <X size={18} />
          </button>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 font-mono text-sm">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-3 rounded-lg ${
                msg.role === 'user' 
                  ? 'bg-terminal-green/20 text-emerald-200 border border-terminal-green/30 rounded-br-none' 
                  : 'bg-gray-800 text-gray-300 border border-gray-700 rounded-bl-none'
              }`}>
                {msg.text}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-gray-800 p-3 rounded-lg rounded-bl-none flex gap-1">
                <span className="w-2 h-2 bg-terminal-green rounded-full animate-bounce"></span>
                <span className="w-2 h-2 bg-terminal-green rounded-full animate-bounce delay-100"></span>
                <span className="w-2 h-2 bg-terminal-green rounded-full animate-bounce delay-200"></span>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input */}
        <div className="p-3 bg-gray-950 border-t border-gray-800 flex gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Query event database..."
            className="flex-1 bg-gray-900 border border-gray-800 rounded px-3 py-2 text-sm font-mono text-white focus:outline-none focus:border-terminal-green/50"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading}
            className="p-2 bg-terminal-green text-terminal-black rounded hover:bg-emerald-400 transition-colors disabled:opacity-50"
          >
            {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
          </button>
        </div>
      </div>
    </>
  );
};

export default TerminalChat;

