             style={{ width: `${Math.min(scrollProgress * 100, 100)}%` }}
           >
             {/* Leading Edge Sparkle */}
             <div className="absolute right-0 top-1/2 -translate-y-1/2 w-2 h-2 bg-white rounded-full shadow-[0_0_5px_white]"></div>
